#!/usr/bin/env bash
# Pre-tool hook for Claude Code, Kiro CLI, and Cursor. Blocks posting GitHub comments,
# replies or reviews (gh via the shell tool) and Jira comments (Atlassian MCP) unless
# the text contains the calling agent's prefix: "[Generated by Claude]",
# "[Generated by Kiro]", or "[Generated by Cursor]".
set -euo pipefail

input="$(cat)"
tool_name="$(jq -r '.tool_name // ""' <<<"$input")"
event="$(jq -r '.hook_event_name // ""' <<<"$input")"
cursor_version="$(jq -r '.cursor_version // ""' <<<"$input")"

# Cursor names the event "preToolUse", the same string Kiro uses, and sends
# cursor_version on every hook. The version field is what distinguishes them.
agent=claude
if [[ -n "$cursor_version" && "$cursor_version" != "null" ]]; then
    agent=cursor
elif [[ "$event" == "preToolUse" ]]; then
    agent=kiro
fi

case "$agent" in
    cursor) PREFIX='[Generated by Cursor]' ;;
    kiro) PREFIX='[Generated by Kiro]' ;;
    *) PREFIX='[Generated by Claude]' ;;
esac

allow() {
    # Cursor permission hooks block on empty or invalid JSON. Claude and Kiro allow on exit 0.
    if [[ "$agent" == "cursor" ]]; then
        jq -n '{permission: "allow"}'
    fi
    exit 0
}

deny() {
    case "$agent" in
        kiro)
            # Kiro CLI blocks on exit 2 and returns stderr to the model.
            echo "$1" >&2
            exit 2
            ;;
        cursor)
            jq -n --arg reason "$1" \
                '{permission: "deny", user_message: $reason, agent_message: $reason}'
            exit 0
            ;;
        *)
            # Claude Code reads a JSON decision.
            jq -n --arg reason "$1" \
                '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $reason}}'
            exit 0
            ;;
    esac
}

if [[ "$tool_name" == *addCommentToJiraIssue || "$tool_name" == *addOrEditJiraIssueComment ]]; then
    comment_body="$(jq -r '.tool_input.commentBody // ""' <<<"$input")"
    grep -qF "$PREFIX" <<<"$comment_body" ||
        deny "Jira comments must start with \"$PREFIX\". Put the prefix at the start of commentBody."
    allow
fi

command="$(jq -r '.tool_input.command // .command // ""' <<<"$input")"

posts_comment=false
if grep -qE 'gh +(pr|issue) +comment\b' <<<"$command"; then
    posts_comment=true
elif grep -qE 'gh +pr +review\b' <<<"$command" && grep -qE '(^| )(-b|--body|-F|--body-file)( |=)' <<<"$command"; then
    posts_comment=true
elif grep -qE 'gh +api\b' <<<"$command" && grep -qE '/(comments|replies|reviews)\b' <<<"$command" &&
    grep -qE '(^| )(-f|-F|--field|--raw-field|--input|-X|--method)( |=)' <<<"$command" &&
    ! grep -qiE '(-X|--method)( |=)GET\b' <<<"$command"; then
    posts_comment=true
fi

if [[ "$posts_comment" == true ]] && ! grep -qF "$PREFIX" <<<"$command"; then
    deny "Comments posted to GitHub must start with \"$PREFIX\". Put the prefix at the start of the body, inline in the command (not via a body file)."
fi

allow
